/* ---- shared rendering kit for the Energy Analytics views ----
   Every view is a custom widget fed by appsmith.model. No external libraries:
   the charts are hand-drawn SVG, so nothing has to load from a CDN. */

var C = { blue:'#1769e8', teal:'#10a6a0', purple:'#7155d9', green:'#14975f',
          amber:'#ed9b23', red:'#e64a55', grey:'#aab5c4' };
var SERIES = [C.blue, C.teal, C.purple, C.amber, C.red, C.green, C.grey];

function esc(s){ return String(s==null?'':s).replace(/[&<>"']/g, function(c){
  return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]; }); }

function money(n){
  var v = Number(n)||0, a = Math.abs(v), s = v<0?'-':'';
  if(a>=1e9) return s+'$'+(a/1e9).toFixed(2)+'B';
  if(a>=1e6) return s+'$'+(a/1e6).toFixed(2)+'M';
  if(a>=1e3) return s+'$'+Math.round(a/1e3)+'K';
  return s+'$'+a.toFixed(0);
}
function num(n,dp){
  var v = Number(n)||0, a = Math.abs(v), s = v<0?'-':'';
  if(a>=1e9) return s+(a/1e9).toFixed(1)+'B';
  if(a>=1e6) return s+(a/1e6).toFixed(1)+'M';
  if(a>=1e3) return s+(a/1e3).toFixed(1)+'K';
  return s+a.toFixed(dp==null?0:dp);
}
function pct(n,dp){ return (Number(n)||0).toFixed(dp==null?1:dp)+'%'; }

/* A delta reads red when it rises and green when it falls: for cost and consumption,
   up is bad. Views that want the opposite pass invert = true. */
function deltaHtml(d, invert){
  if(d==null || !isFinite(d)) return '<small>&nbsp;</small>';
  var up = d>0, good = invert ? up : !up;
  return '<small class="'+(good?'down':'up')+'">'+(up?'&uarr; ':'&darr; ')+pct(Math.abs(d))+'</small>';
}

function kpiStrip(kpis){
  if(!kpis || !kpis.length) return '';
  return '<div class="grid kpis">' + kpis.map(function(k){
    return '<div class="card kpi"><div class="bubble '+(k.tone||'')+'">'+esc(k.icon||'')+'</div>'+
      '<div><small>'+esc(k.label)+'</small><b>'+esc(k.value)+'</b>'+
      (k.delta!=null ? deltaHtml(k.delta)+'<small>'+esc(k.note||'')+'</small>'
                     : '<small>'+esc(k.note||'')+'</small>')+
      '</div></div>';
  }).join('') + '</div>';
}

/* ---- SVG primitives ----
   All charts draw into a fixed viewBox and scale with preserveAspectRatio, so they
   stay legible whatever width Appsmith gives the widget. */

function svgOpen(w,h,cls){
  return '<svg class="chart'+(cls?' '+cls:'')+'" viewBox="0 0 '+w+' '+h+'" preserveAspectRatio="none">';
}
function gridLines(x0,y0,x1,y1,rows){
  var out='', step=(y1-y0)/rows;
  for(var i=0;i<=rows;i++){ var y=y0+step*i;
    out+='<line x1="'+x0+'" y1="'+y+'" x2="'+x1+'" y2="'+y+'" stroke="#e3eaf3" stroke-width="1"/>'; }
  return out;
}
function scale(vals){
  var mx = 0;
  vals.forEach(function(v){ if(v!=null && isFinite(v) && v>mx) mx=v; });
  return mx || 1;
}

/* Multi-series line chart. series = [{name, color, dash, values:[]}] */
function lineChart(labels, series, h){
  h = h||230; var w=760, x0=44, y0=14, y1=h-30, x1=w-10;
  if(!labels.length) return '<div class="empty">No data in this window</div>';
  var mx = scale([].concat.apply([], series.map(function(s){return s.values;})));
  var step = labels.length>1 ? (x1-x0)/(labels.length-1) : 0;
  var out = svgOpen(w,h) + gridLines(x0,y0,y1,x1,4);

  series.forEach(function(s){
    var d='', started=false;
    s.values.forEach(function(v,i){
      if(v==null || !isFinite(v)) { started=false; return; }   // a gap breaks the line
      var x = x0+step*i, y = y1-(v/mx)*(y1-y0);
      d += (started?'L':'M')+x.toFixed(1)+' '+y.toFixed(1);
      started = true;
    });
    if(d) out += '<path d="'+d+'" fill="none" stroke="'+s.color+'" stroke-width="2.5" '+
                 (s.dash?'stroke-dasharray="6 5" ':'')+'stroke-linejoin="round"/>';
  });

  out += axisLabels(labels, x0, step, y1, w, mx, y0);
  return out+'</svg>';
}

/* x labels thinned to ~8, plus a max marker on the y axis */
function axisLabels(labels, x0, step, y1, w, mx, y0){
  var every = Math.max(1, Math.ceil(labels.length/8)), out='';
  out += '<text x="4" y="'+(y0+9)+'" font-size="10" fill="#8494a8">'+num(mx)+'</text>';
  labels.forEach(function(l,i){
    if(i%every) return;
    var x = x0+step*i;
    out += '<text x="'+x.toFixed(0)+'" y="'+(y1+16)+'" font-size="10" fill="#8494a8" text-anchor="middle">'+esc(l)+'</text>';
  });
  return out;
}

/* Stacked column chart. series = [{name, color, values:[]}] */
function stackedBars(labels, series, h){
  h = h||230; var w=760, x0=44, y0=14, y1=h-30, x1=w-10;
  if(!labels.length) return '<div class="empty">No data in this window</div>';
  var totals = labels.map(function(_,i){
    return series.reduce(function(a,s){ return a + (Number(s.values[i])||0); },0); });
  var mx = scale(totals);
  var slot = (x1-x0)/labels.length, bw = Math.max(3, Math.min(26, slot*0.62));
  var out = svgOpen(w,h) + gridLines(x0,y0,y1,x1,4);

  labels.forEach(function(_,i){
    var x = x0 + slot*i + (slot-bw)/2, acc = 0;
    series.forEach(function(s){
      var v = Number(s.values[i])||0; if(!v) return;
      var bh = (v/mx)*(y1-y0), y = y1-acc-bh; acc += bh;
      out += '<rect x="'+x.toFixed(1)+'" y="'+y.toFixed(1)+'" width="'+bw.toFixed(1)+
             '" height="'+Math.max(0.5,bh).toFixed(1)+'" fill="'+s.color+'"/>';
    });
  });
  out += axisLabels(labels, x0+slot/2, slot, y1, w, mx, y0);
  return out+'</svg>';
}

/* Columns + an overlaid line on its own scale — the charges-vs-consumption pairing. */
function comboChart(labels, bars, line, h){
  h = h||230; var w=760, x0=44, y0=14, y1=h-30, x1=w-10;
  if(!labels.length) return '<div class="empty">No data in this window</div>';
  var mb = scale(bars.values), ml = scale(line.values);
  var slot = (x1-x0)/labels.length, bw = Math.max(3, Math.min(26, slot*0.6));
  var out = svgOpen(w,h) + gridLines(x0,y0,y1,x1,4);

  labels.forEach(function(_,i){
    var v = Number(bars.values[i])||0;
    var bh = (v/mb)*(y1-y0), x = x0+slot*i+(slot-bw)/2;
    out += '<rect x="'+x.toFixed(1)+'" y="'+(y1-bh).toFixed(1)+'" width="'+bw.toFixed(1)+
           '" height="'+Math.max(0.5,bh).toFixed(1)+'" fill="'+bars.color+'" opacity=".75"/>';
  });
  var d='', started=false;
  line.values.forEach(function(v,i){
    if(v==null||!isFinite(v)){ started=false; return; }
    var x = x0+slot*i+slot/2, y = y1-(v/ml)*(y1-y0);
    d += (started?'L':'M')+x.toFixed(1)+' '+y.toFixed(1); started=true;
  });
  if(d) out += '<path d="'+d+'" fill="none" stroke="'+line.color+'" stroke-width="2.5"/>';
  out += axisLabels(labels, x0+slot/2, slot, y1, w, mb, y0);
  return out+'</svg>';
}

/* Actual line, forecast dashes and a confidence band. */
function forecastChart(points, h){
  h = h||230; var w=760, x0=44, y0=14, y1=h-30, x1=w-10;
  if(!points.length) return '<div class="empty">No data in this window</div>';
  var mx = scale(points.map(function(p){ return p.high!=null?p.high:p.charges; }));
  var step = points.length>1 ? (x1-x0)/(points.length-1) : 0;
  var X = function(i){ return x0+step*i; }, Y = function(v){ return y1-(v/mx)*(y1-y0); };
  var out = svgOpen(w,h) + gridLines(x0,y0,y1,x1,4);

  var band = points.map(function(p,i){ return p.forecast&&p.high!=null?{i:i,p:p}:null; }).filter(Boolean);
  if(band.length>1){
    var up = band.map(function(b){ return X(b.i).toFixed(1)+' '+Y(b.p.high).toFixed(1); });
    var dn = band.slice().reverse().map(function(b){ return X(b.i).toFixed(1)+' '+Y(b.p.low).toFixed(1); });
    out += '<path d="M'+up.join('L')+'L'+dn.join('L')+'Z" fill="#dce9ff" opacity=".7"/>';
  }
  ['actual','forecast'].forEach(function(kind){
    var d='', started=false;
    points.forEach(function(p,i){
      var mine = kind==='actual' ? !p.forecast : p.forecast;
      /* join the two runs by letting the forecast start at the last actual point */
      if(kind==='forecast' && !p.forecast && points[i+1] && points[i+1].forecast) mine = true;
      if(!mine){ started=false; return; }
      d += (started?'L':'M')+X(i).toFixed(1)+' '+Y(p.charges).toFixed(1); started=true;
    });
    if(d) out += '<path d="'+d+'" fill="none" stroke="'+C.blue+'" stroke-width="2.5"'+
                 (kind==='forecast'?' stroke-dasharray="6 5"':'')+'/>';
  });
  out += axisLabels(points.map(function(p){return p.label;}), x0, step, y1, w, mx, y0);
  return out+'</svg>';
}

/* Scatter with an optional least-squares line. */
function scatterChart(points, fit, h, xlab, ylab){
  h = h||210; var w=560, x0=46, y0=12, y1=h-28, x1=w-12;
  if(!points.length) return '<div class="empty">Not enough data to plot</div>';
  var xs = points.map(function(p){return p.x;}), ys = points.map(function(p){return p.y;});
  var xmin=Math.min.apply(null,xs), xmax=Math.max.apply(null,xs);
  var ymin=Math.min.apply(null,ys), ymax=Math.max.apply(null,ys);
  if(xmax===xmin) xmax=xmin+1; if(ymax===ymin) ymax=ymin+1;
  var X=function(v){ return x0+(v-xmin)/(xmax-xmin)*(x1-x0); };
  var Y=function(v){ return y1-(v-ymin)/(ymax-ymin)*(y1-y0); };

  var out = '<svg class="chart" viewBox="0 0 '+w+' '+h+'">' + gridLines(x0,y0,y1,x1,3);
  if(fit){
    var a=X(xmin), b=Y(fit.intercept+fit.slope*xmin), c=X(xmax), d=Y(fit.intercept+fit.slope*xmax);
    out += '<line x1="'+a.toFixed(1)+'" y1="'+b.toFixed(1)+'" x2="'+c.toFixed(1)+'" y2="'+d.toFixed(1)+
           '" stroke="'+C.teal+'" stroke-width="2"/>';
  }
  points.forEach(function(p){
    out += '<circle cx="'+X(p.x).toFixed(1)+'" cy="'+Y(p.y).toFixed(1)+'" r="3.5" fill="'+C.blue+'" opacity=".75"><title>'+
           esc((p.label||p.location||'')+' — '+num(p.x)+' / '+num(p.y))+'</title></circle>';
  });
  out += '<text x="'+(x0+(x1-x0)/2)+'" y="'+(h-4)+'" font-size="10" fill="#8494a8" text-anchor="middle">'+esc(xlab||'')+'</text>';
  out += '<text x="6" y="'+(y0+8)+'" font-size="10" fill="#8494a8">'+esc(ylab||'')+'</text>';
  return out+'</svg>';
}

/* Donut built from stroked arcs, with the total in the middle. */
function donut(items, centre){
  var total = items.reduce(function(a,i){ return a+Math.abs(i.charges!=null?i.charges:i.count); },0);
  if(!total) return '<div class="empty">No data</div>';
  var r=54, cx=70, cy=70, circ=2*Math.PI*r, off=0;
  var out='<svg viewBox="0 0 140 140" style="width:140px;height:140px;display:block;margin:auto">';
  items.forEach(function(it,i){
    var v = Math.abs(it.charges!=null?it.charges:it.count);
    var frac = v/total, len = frac*circ;
    out += '<circle cx="'+cx+'" cy="'+cy+'" r="'+r+'" fill="none" stroke="'+SERIES[i%SERIES.length]+
           '" stroke-width="20" stroke-dasharray="'+len.toFixed(2)+' '+(circ-len).toFixed(2)+
           '" stroke-dashoffset="'+(-off).toFixed(2)+'" transform="rotate(-90 '+cx+' '+cy+')"><title>'+
           esc((it.name||it.code)+' '+pct(frac*100))+'</title></circle>';
    off += len;
  });
  out += '<text x="'+cx+'" y="'+(cy+5)+'" text-anchor="middle" font-size="15" font-weight="700" fill="#11213d">'+esc(centre||'')+'</text>';
  return out+'</svg>';
}

function legend(items){
  return '<div class="legend">' + items.map(function(it,i){
    return '<span><i class="dot" style="background:'+(it.color||SERIES[i%SERIES.length])+'"></i>'+esc(it.name)+'</span>';
  }).join('') + '</div>';
}

function barRow(label, value, max, text, teal){
  var w = max ? Math.max(1, Math.min(100, (value/max)*100)) : 0;
  return '<tr><td>'+esc(label)+'</td><td style="width:45%"><div class="bar'+(teal?' teal':'')+
         '"><i style="width:'+w.toFixed(1)+'%"></i></div></td><td class="num">'+esc(text)+'</td></tr>';
}

function gapNote(gaps){
  if(!gaps || !gaps.length) return '';
  return gaps.map(function(g){
    return '<div class="gap"><b>'+esc(g.field)+' — no source in UBM</b>'+esc(g.note)+'</div>';
  }).join('');
}

function mount(render){
  function draw(){
    var m = (appsmith && appsmith.model) || {};
    try { document.getElementById('root').innerHTML = render(m); }
    catch(e){ document.getElementById('root').innerHTML =
      '<div class="empty">Could not render this view: '+esc(e.message)+'</div>'; }
  }
  draw();
  if(appsmith && typeof appsmith.onModelChange === 'function') appsmith.onModelChange(draw);
}

/* ---- Cost & Forecast ---- */
mount(function(m){
  if(m.empty || !m.kpis || !m.kpis.length)
    return '<div class="card empty">No billing rows for this customer and filter set.</div>';

  var out = kpiStrip(m.kpis);
  var s = m.series||[];

  out += '<div class="grid two">';
  out += '<div class="card"><h2>Charges vs consumption</h2>' +
    comboChart(s.map(function(p){return p.label;}),
      {color:'#a9c9fa', values:s.map(function(p){return p.charges;})},
      {color:C.teal,   values:s.map(function(p){return p.consumption;})}) +
    legend([{name:'Charges',color:'#a9c9fa'},{name:'Consumption',color:C.teal}]) +
    '<div class="note">Charges and consumption are drawn on separate scales.</div></div>';

  out += '<div class="card"><h2>Charge forecast</h2>' + forecastChart(m.forecast||[]) +
    legend([{name:'Actual',color:C.blue},{name:'Forecast (dashed)',color:C.blue},{name:'Confidence band',color:'#dce9ff'}]) +
    '<div class="note">Seasonal average of the loaded history, grown by the year-on-year trend. ' +
    'UBM holds no forecast table — this is computed in the browser.</div></div>';
  out += '</div>';

  out += '<div class="grid three" style="margin-top:12px">';

  var comp = m.composition||[];
  var mxC = comp.length ? comp[0].charges : 0;
  out += '<div class="card"><h2>Charge composition</h2>' +
    (comp.length
      ? '<table>' + comp.map(function(c){
          return barRow(c.name, c.charges, mxC, money(c.charges));
        }).join('') + '</table><div class="note">From the analytics_monthly_feed components, not the usage table.</div>'
      : '<div class="empty">No charge components on these bills</div>') + '</div>';

  var uc = (m.unitCostByLocation||[]).slice(0,8);
  var mxU = uc.length ? uc[0].unitCost : 0;
  out += '<div class="card"><h2>Unit cost by location</h2>' +
    (uc.length
      ? '<table>' + uc.map(function(r){
          return barRow(r.location, r.unitCost, mxU, '$'+r.unitCost.toFixed(3), true);
        }).join('') + '</table>'
      : '<div class="empty">No consumption to divide by</div>') + '</div>';

  var dr = m.drivers||{points:[],fit:null};
  var above = (dr.points||[]).filter(function(p){ return p.above; }).length;
  out += '<div class="card"><h2>Cost drivers</h2>' +
    scatterChart(dr.points||[], dr.fit, 175, 'Consumption', 'Charges') +
    '<div class="note">' + above + ' of ' + (dr.points||[]).length +
    ' locations sit above the trend line — they cost more than their consumption predicts.</div></div>';

  out += '</div>';
  return out;
});
